import{_ as t,o,c as r,a2 as n}from"./chunks/framework.D_ZOUi6P.js";const m=JSON.parse('{"title":"Common understanding","description":"","frontmatter":{},"headers":[],"relativePath":"development/common-language.md","filePath":"development/common-language.md","lastUpdated":1793371425000}'),a={name:"development/common-language.md"};function s(i,e,l,h,d,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="common-understanding" tabindex="-1">Common understanding <a class="header-anchor" href="#common-understanding" aria-label="Permalink to &quot;Common understanding&quot;">​</a></h1><p>Saluki is a large software project with a growing number of contributors. In order to ensure everyone is on the same page, we need to make sure we&#39;re all using the same terminology and have a common understanding on the various areas of the project and the tools and processes for developing it.</p><h2 id="writing-style" tabindex="-1">Writing style <a class="header-anchor" href="#writing-style" aria-label="Permalink to &quot;Writing style&quot;">​</a></h2><p>We strive to use ASD-STE100, or &quot;Simplified Technical English,&quot; when writing user-facing code comments and documentation. ASD-STE100 is a large, highly opinionated reference for technical writing, but can generally be summarized as having the following high-level aspects:</p><ul><li>prefer using &quot;active voice&quot; (&quot;The dog bit the postal carrier.&quot; instead of &quot;The postal carrier was bitten by the dog.&quot;)</li><li>use short sentences (no more than 20-25 words per sentence) and short paragraphs (no more than 5-6 sentences per paragraph)</li><li>avoid synonyms where possible, preferring simple nouns and verbs used consistently throughout the codebase</li></ul><p>ASD-STE100 consists of two main parts -- the writing rules and the dictionary -- which are designed to be used together. We don&#39;t expect users to precisely follow the dictionary portion of ASD-STE100, but users are expected to write in a straightforward manner -- following the above rules, preferring consistent, simple wording -- whether by hand or through agentic help.</p><h2 id="requirement-levels" tabindex="-1">Requirement levels <a class="header-anchor" href="#requirement-levels" aria-label="Permalink to &quot;Requirement levels&quot;">​</a></h2><p>If you have ever read an IETF RFC, you may be familiar with the sight of words like <em>MUST</em> and <em>SHOULD NOT</em>. <a href="https://datatracker.ietf.org/doc/html/rfc2119" target="_blank" rel="noreferrer">RFC 2119</a> defines these as <em>requirement levels</em>, where the use of these terms indicates whether or not something is required, or is a suggestion, or if the behavior is purely optional.</p><p>These requirement levels are used throughout the documentation to help clarify the expectations around certain processes. You&#39;re encouraged to read the RFC, but here&#39;s a quick rundown:</p><ul><li><strong>MUST</strong>/<strong>SHALL</strong>: this is an absolute requirement</li><li><strong>MUST NOT</strong>/<strong>SHALL NOT</strong>: this is an absolute prohibition</li><li><strong>SHOULD</strong>/<strong>RECOMMENDED</strong>: you really should do this, but there may be valid reasons not to</li><li><strong>SHOULD NOT</strong>/<strong>NOT RECOMMENDED</strong>: you really shouldn&#39;t do this, but there may be valid reasons to do so</li><li><strong>MAY</strong>/<strong>OPTIONAL</strong>: this is legitimately optional (&quot;dealer&#39;s choice&quot;)</li></ul><p>Like RFC 2119 mentions, these should be used sparingly and only when necessary to clarify expectations... so if you see them, pay attention.</p>',11)])])}const c=t(a,[["render",s]]);export{m as __pageData,c as default};
